/**
 * Booking reference and idempotency-key helpers.
 *
 * References are generated by the database (`private.booking_reference()`), never
 * by the browser, and are validated here only to display or accept them safely. A
 * reference is never an authorisation credential: there is no public
 * read-by-reference endpoint, and knowing a reference grants nothing.
 */

/** Reference shape produced by the database: `2W-` plus ten Crockford-safe chars. */
export const BOOKING_REFERENCE_PATTERN = /^2W-[0-9A-HJKMNP-TV-Z]{10}$/;

export function isValidBookingReference(value: unknown): value is string {
  return typeof value === "string" && BOOKING_REFERENCE_PATTERN.test(value.trim());
}

/** Upper-cases and trims a user-supplied reference for comparison only. */
export function normaliseBookingReference(value: string): string {
  return value.trim().toUpperCase();
}

/**
 * Creates a client-side idempotency key.
 *
 * The key confirms a retry is the same submission; it is not an anti-spam or
 * authorisation mechanism, and the database enforces uniqueness per scope.
 */
export function createIdempotencyKey(): string {
  const source =
    typeof globalThis.crypto !== "undefined" && "randomUUID" in globalThis.crypto
      ? globalThis.crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return source.replace(/-/g, "");
}

/** True when a key satisfies the database's length constraint (16–128). */
export function isValidIdempotencyKey(value: unknown): value is string {
  return typeof value === "string" && value.length >= 16 && value.length <= 128;
}
